mapper.select:
SELECT WORD_ID AS "id", WORD_NM AS "nm", WORD_ENG_ABRV_NM AS "engAbrvNm", WORD_ENG_NM AS "engNm",
       WORD_CLSF_YN AS "clsfYn", DOMAIN_CLSF_NM AS "domainClsfNm", DICT_ID AS "dictId"
  FROM TB_WORD WHERE WORD_ID = #{id}

SELECT TERMS_ID AS "id", TERMS_NM AS "nm", TERMS_ENG_ABRV_NM AS "engAbrvNm", DOMAIN_NM AS "domainNm",
       CODE_GRP AS "codeGrp", CODE_TP AS "codeTp", PARENT_CODE_GRP AS "parentCodeGrp", DICT_ID AS "dictId"
  FROM TB_TERMS WHERE TERMS_ID = #{id}

mapper.insert:
INSERT INTO TB_DOMAIN_GRP (DOMAIN_GRP_ID, DOMAIN_GRP_NM, COMM_STND_YN, CRET_DT, CRET_USER_ID, DICT_ID, DFLT_DATA_TYPE, CLSF_WORD_NM, SORT_ORDER)
SELECT #{newId}, DOMAIN_GRP_NM, 'Y', to_char(now(), 'YYYYMMDDHH24MISS'), #{userId}, #{targetDictId}, DFLT_DATA_TYPE, CLSF_WORD_NM, COALESCE(SORT_ORDER, 0)
  FROM TB_DOMAIN_GRP WHERE DICT_ID = #{sourceDictId} AND DOMAIN_GRP_NM = #{nm}

INSERT INTO TB_CODE_DATA (CODE_ID, CODE_GRP, CODE_NM, CODE_ENG_NM, CODE_VAL, CODE_VAL_DESC, PARENT_CODE_VAL, CRET_DT, CRET_USER_ID, DICT_ID)
SELECT substr(md5(random()::text || S.CODE_ID), 1, 22), S.CODE_GRP, S.CODE_NM, S.CODE_ENG_NM, S.CODE_VAL, S.CODE_VAL_DESC, S.PARENT_CODE_VAL,
       to_char(now(), 'YYYYMMDDHH24MISS'), #{userId}, #{targetDictId}
  FROM TB_CODE_DATA S
 WHERE S.DICT_ID = #{sourceDictId} AND S.CODE_GRP = #{codeGrp}
   AND NOT EXISTS (SELECT 1 FROM TB_CODE_DATA T WHERE T.DICT_ID = #{targetDictId} AND T.CODE_NM = S.CODE_NM AND T.CODE_VAL = S.CODE_VAL)
